import os, re, sys
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from shots import run, BASE, OUT, open_last_week, phone_of, show_phone, pick_phone, pick_phone_id, unlock

# Round nine, 17 Nov (decisions 100 to 105): overtime at both rates on one day, the Weekend time
# stamp for Saturdays, Sundays and bank holidays, bank holidays in Admin, weekend work on the week
# and month ahead and both phones, Profitability for the managing director, and email drafts.
results = []
def check(name, cond, detail=""):
    results.append((name, bool(cond), str(detail)))
def data(page, expr):
    return page.evaluate("(() => { const s = JSON.parse(localStorage.getItem('cod.data')).state; const db = s.db; const day = s.day; return " + expr + "; })()")
def go(page, path, sel="main h1"):
    page.goto(BASE + path); page.wait_for_selector(sel); page.wait_for_timeout(500)
def as_role(page, name):
    page.get_by_role("button", name="Account menu").click(); page.get_by_role("menuitem", name=name).click(); page.wait_for_timeout(500)
def toast(page):
    return page.locator("[aria-live=polite]").last.inner_text()
def reset(page):
    page.get_by_role("button", name="Account menu").click(); page.get_by_role("menuitem", name="Reset demo data").click()
    page.get_by_role("button", name="Reset demo data").click(); page.wait_for_timeout(400)
SCROLLS = "[...document.querySelectorAll('main *')].filter(e => e.tagName !== 'NAV' && !e.className.includes?.('truncate') && !e.className.includes?.('sr-only') && e.clientWidth > 0 && e.scrollWidth > e.clientWidth + 1 && getComputedStyle(e).overflowX !== 'visible').length"
# Dates worked out in the page, the way the app does: this week's Monday, and days from it.
MON = "(() => { const d = new Date(day + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() - ((d.getUTCDay() + 6) % 7)); return d.toISOString().slice(0, 10) })()"
def plus(n):
    return f"(() => {{ const d = new Date({MON} + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + ({n})); return d.toISOString().slice(0, 10) }})()"

def steps(page, ctx):
    page.goto(BASE + "/"); page.wait_for_url("**/sign-in")
    page.fill("#username", "demo"); page.fill("#password", "demo"); page.click("button[type=submit]")
    page.wait_for_url("**/who"); page.get_by_role("button", name="Managing director").click(); page.wait_for_url("**/dashboard")
    main = page.locator("main")
    dlg = lambda: page.locator("dialog[open]").last
    reset(page)
    day = data(page, "day")
    last_sat = data(page, plus(-2)); last_sun = data(page, plus(-1)); this_sat = data(page, plus(5)); next_sat = data(page, plus(12))
    pid = lambda code: data(page, f"db.projects.find(p => p.code === '{code}').id")
    stamps = lambda code, date: data(page, f"db.attendance.filter(a => a.projectId === '{pid(code)}' && a.date === '{date}' && a.status === 'restday').map(a => [db.people.find(p => p.id === a.personId).name, a.overtimeHours, a.doubleHours ?? 0]).sort()")

    # ── 1. Timesheet: the rule, and overtime at both rates on a normal day
    go(page, f"/people/timesheet?site={pid('C722')}", "table")
    rules = page.get_by_role("region", name="Overtime rates").inner_text()
    check("Timesheet: the rule says double time after midnight is only for work carried on from the day before", "After midnight, when the work carries on from the day before" in rules and "Monday to Friday, after a normal day's hours, up to midnight" in rules, rules)
    check("Timesheet: an early start is said not to be overtime", "An early start, at 6am or 7am, is not overtime. Overtime begins once a normal day's hours are done: 8 hours, or 7 on a Friday." in rules)
    first = main.locator("tbody tr").first
    who = first.locator("td").first.inner_text().split("\n")[0]
    sel = main.get_by_label(f"Today for {who}")
    check("Timesheet: today is not marked, a full day, a half day, or a full day with overtime", sel.locator("option").all_inner_texts() == ["Not marked", "Full day", "Half day", "Full + overtime"])
    sel.select_option("overtime"); page.wait_for_timeout(200)
    half = main.get_by_label(f"Hours at time and a half for {who}"); dbl = main.get_by_label(f"Hours at double time for {who}")
    check("Timesheet: overtime opens two boxes of hours, one at each rate, starting at one hour at time and a half", half.count() == 1 and dbl.count() == 1 and half.input_value() == "1" and dbl.input_value() == "0")
    half.fill("7.5"); dbl.fill("1.5"); page.wait_for_timeout(200)
    a = data(page, f"db.attendance.find(a => a.projectId === '{pid('C722')}' && a.date === day && db.people.find(p => p.id === a.personId).name === '{who}')")
    check("Timesheet: a day holds hours at time and a half and at double time together", a and a["status"] == "full" and a["overtimeHours"] == 7.5 and a.get("doubleHours") == 1.5, a)
    half.fill("0"); page.wait_for_timeout(200)
    check("Timesheet: double time with no time and a half is saved, with a warning beside it", "Double time with no time and a half. An early start is not overtime." in first.inner_text() and data(page, f"db.attendance.find(a => a.projectId === '{pid('C722')}' && a.date === day && a.doubleHours === 1.5).overtimeHours") == 0, first.inner_text())
    check("Timesheet: the boxes stay open while both are being typed", half.count() == 1 and dbl.count() == 1)
    dbl.fill("0"); page.wait_for_timeout(200)
    sel.select_option("full"); page.wait_for_timeout(200)
    check("Timesheet: back to a full day leaves no overtime behind", main.get_by_label(f"Hours at double time for {who}").count() == 0 and data(page, f"(() => {{ const a = db.attendance.find(a => a.projectId === '{pid('C722')}' && a.date === day); return [a.status, a.overtimeHours, a.doubleHours ?? null] }})()") == ["full", 0, None])
    page.screenshot(path=f"{OUT}/910-timesheet-today.png")

    # Correcting a sent day to both rates
    go(page, f"/people/timesheet?site={pid('C719')}", "table")
    page.get_by_role("button", name="Earlier week").click(); page.wait_for_timeout(300)
    cell = main.locator("tbody tr").first.get_by_role("button", name=re.compile("Correct this day")).first
    cell.click(); page.wait_for_timeout(250)
    d = dlg()
    check("Correct: the same four choices", d.get_by_label("Should be").locator("option").all_inner_texts() == ["Not in", "Full day", "Half day", "Full + overtime"])
    d.get_by_label("Should be").select_option("overtime"); page.wait_for_timeout(150)
    d.get_by_label("Hours at time and a half").fill("0"); d.get_by_label("Hours at double time").fill("2"); page.wait_for_timeout(150)
    check("Correct: double time alone is warned about, and flagged for the weekly check", "Double time with no time and a half. An early start is not overtime. It will be saved, and flagged for the manager's weekly check." in d.inner_text())
    d.get_by_label("Hours at time and a half").fill("6"); d.get_by_label("Reason for the correction").fill("Worked on past midnight to finish the pour")
    d.get_by_role("button", name="Save correction").click(); page.wait_for_timeout(300)
    check("Correct: a day is corrected to hours at both rates", "to Full +6h x1.5 +2h x2" in toast(page) and data(page, "db.attendanceChanges[0].to") == "Full +6h x1.5 +2h x2", toast(page))

    # ── 2. The Weekend time stamp
    reset(page)
    go(page, f"/people/timesheet?site={pid('C720')}", "table")
    btn = main.get_by_role("button", name="Overtime time stamp")
    box = btn.bounding_box()
    check("Timesheet: an Overtime time stamp button at the top right, beside Send today's time stamps (Weekend time stamp until round ten)", btn.count() == 1 and box and box["y"] < 130 and box["x"] > 900, box)
    sec = main.locator("section", has=page.get_by_role("heading", name="Overtime", exact=True))
    check("Timesheet: this week's sheet has no weekend time stamp yet, and says where last weekend's are", sec.get_by_text("Overtime time stamp", exact=True).count() == 0 and "Last weekend has 2 time stamps on this site. They are on last week's sheet" in sec.inner_text(), sec.inner_text())
    btn.click(); page.wait_for_timeout(300)
    d = dlg()
    days = d.get_by_label("Day").locator("option").all_inner_texts()
    check("Stamp: the day is a Saturday, a Sunday or a bank holiday that has been, newest first", len(days) == 2 and days[0].startswith("Sun") and days[1].startswith("Sat"), days)
    crew = d.get_by_role("list", name="People to stamp").locator("> li")
    check("Stamp: this site's crew to tick, and a box to add anyone else in the firm", crew.count() == data(page, f"db.assignments.filter(a => a.projectId === '{pid('C720')}').length") and d.get_by_label("Add someone from another site").locator("option").count() > 10)
    check("Stamp: a Sunday is all double time, so time and a half cannot be typed", d.get_by_label("Hours at time and a half").is_disabled() and "Sunday: every hour is at double time." in d.inner_text())
    d.get_by_role("button", name="Save time stamp").click(); page.wait_for_timeout(150)
    check("Stamp: someone has to be ticked", "Tick who worked" in d.get_by_role("alert").inner_text())
    d.get_by_label("Day").select_option(last_sat); page.wait_for_timeout(150)
    check("Stamp: a Saturday takes both rates, with its rule shown", d.get_by_label("Hours at time and a half").is_enabled() and "Saturday: 8am to 12 noon is at time and a half, and after 12 noon is at double time." in d.inner_text())
    crew.nth(0).get_by_role("checkbox").check(); crew.nth(1).get_by_role("checkbox").check()
    d.get_by_label("Add someone from another site").select_option(label="Kevin Shortall, Scaffolder"); page.wait_for_timeout(150)
    check("Stamp: someone from another site joins the list, ticked", crew.count() == data(page, f"db.assignments.filter(a => a.projectId === '{pid('C720')}').length") + 1 and "From another site" in crew.last.inner_text() and crew.last.get_by_role("checkbox").is_checked())
    d.get_by_role("button", name="Save time stamp").click(); page.wait_for_timeout(150)
    check("Stamp: hours are needed", "Enter the hours worked" in d.get_by_role("alert").inner_text())
    d.get_by_label("Hours at time and a half").fill("5"); d.get_by_role("button", name="Save time stamp").click(); page.wait_for_timeout(150)
    check("Stamp: at most four Saturday hours are at time and a half", "At most 4 hours on a Saturday are at time and a half (8am to 12 noon). Put the rest at double time" in d.get_by_role("alert").inner_text())
    d.get_by_label("Hours at time and a half").fill("4"); d.get_by_label("Hours at double time").fill("2.5")
    page.screenshot(path=f"{OUT}/911-weekend-stamp.png")
    d.get_by_role("button", name="Save time stamp").click(); page.wait_for_timeout(400)
    got = stamps("C720", last_sat)
    check("Stamp: one time stamp is saved for each person ticked, with the hours at each rate", len(got) == 3 and all(x[1:] == [4, 2.5] for x in got) and "Kevin Shortall" in [x[0] for x in got] and "3 time stamps saved for Sat" in toast(page), (got, toast(page)))
    rows = main.get_by_role("table", name="Overtime in this week").locator("tbody tr").filter(has_text="Overtime time stamp")
    check("Stamp: the sheet moves to that week and lists them under the grid", f"Week of {int(data(page, plus(-7))[8:])} " in main.inner_text() and rows.count() == 5 and rows.filter(has_text="Kevin Shortall").filter(has_text="4h x1.5 + 2.5h x2").count() == 1, rows.all_inner_texts())
    check("Stamp: it is saved as sent, by whoever stamped it, and logged", data(page, f"db.attendance.filter(a => a.date === '{last_sat}' && a.projectId === '{pid('C720')}').every(a => a.sent && a.savedBy === 'Aidan King')") and data(page, "db.activity[0].what") == "Added an overtime time stamp")
    check("Stamp: the grid is still Monday to Friday", main.locator("table").first.locator("thead th").count() == 7)
    page.screenshot(path=f"{OUT}/912-timesheet-weekend-list.png", full_page=True)
    main.get_by_role("button", name="Overtime time stamp").click(); page.wait_for_timeout(300)
    d = dlg()
    d.get_by_label("Day").select_option(last_sat); crew = d.get_by_role("list", name="People to stamp").locator("> li")
    crew.nth(0).get_by_role("checkbox").check(); d.get_by_label("Hours at double time").fill("1")
    d.get_by_role("button", name="Save time stamp").click(); page.wait_for_timeout(200)
    check("Stamp: a second stamp for the same person, site and day is refused", "already have a time stamp on this site for that day" in d.get_by_role("alert").inner_text() and len(stamps("C720", last_sat)) == 3, d.get_by_role("alert").inner_text())
    d.get_by_role("button", name="Cancel").click(); page.wait_for_timeout(200)

    # Changing and removing a stamp is a correction
    rows.filter(has_text="Kevin Shortall").get_by_role("button", name=re.compile("^Change the time stamp for Kevin Shortall")).click(); page.wait_for_timeout(250)
    d = dlg()
    check("Change: needs a reason before it can be saved or removed", d.get_by_role("button", name="Save correction").is_disabled() and d.get_by_role("button", name="Remove time stamp").is_disabled())
    d.get_by_label("Hours at double time").fill("1"); d.get_by_label("Reason for the change").fill("Went at 1pm"); d.get_by_role("button", name="Save correction").click(); page.wait_for_timeout(300)
    check("Change: the hours change and the old ones are kept as a correction", rows.filter(has_text="Kevin Shortall").filter(has_text="4h x1.5 + 1h x2").count() == 1 and data(page, "[db.attendanceChanges[0].from, db.attendanceChanges[0].to, db.attendanceChanges[0].reason]") == ["4h x1.5 + 2.5h x2", "4h x1.5 + 1h x2", "Went at 1pm"])
    rows.filter(has_text="Kevin Shortall").get_by_role("button", name=re.compile("^Change")).click(); page.wait_for_timeout(250)
    d = dlg(); d.get_by_label("Reason for the change").fill("Stamped by mistake"); d.get_by_role("button", name="Remove time stamp").click(); page.wait_for_timeout(300)
    check("Change: a stamp can be removed, with the reason kept", rows.count() == 4 and data(page, "db.attendanceChanges[0].to") == "Not in" and "Time stamp removed for Kevin Shortall" in toast(page), toast(page))

    # A bank holiday in the grid
    bh = data(page, "db.bankHolidays.filter(h => h.date < day && ![0, 6].includes(new Date(h.date + 'T12:00:00Z').getUTCDay())).pop()")
    go(page, f"/people/timesheet?site={pid('C721')}", "table")
    for _ in range(8):
        if bh["name"] in main.locator("table").first.locator("thead").inner_text(): break
        page.get_by_role("button", name="Earlier week").click(); page.wait_for_timeout(250)
    head = main.locator("table").first.locator("thead").inner_text()
    col = [i for i, t in enumerate(main.locator("table").first.locator("thead th").all_inner_texts()) if bh["name"] in t][0]
    cells = main.locator("table").first.locator(f"tbody tr td:nth-child({col + 1})").all_inner_texts()
    check("Bank holiday: its column is named, and nobody is marked a normal day on it", bh["name"] in head and all(c.strip() == "Bank holiday" for c in cells) and data(page, f"db.attendance.filter(a => a.date === '{bh['date']}' && a.status !== 'restday').length") == 0, (head, cells))
    hol = main.get_by_role("table", name="Overtime in this week").locator("tbody tr").filter(has_text="Overtime time stamp")
    check("Bank holiday: those who worked it are stamped at double time, under the grid", hol.count() == 2 and all("5h x2" in t and bh["name"] in t for t in hol.all_inner_texts()), hol.all_inner_texts())
    page.screenshot(path=f"{OUT}/913-timesheet-bank-holiday.png", full_page=True)

    # ── 3. Attendance history
    go(page, "/people/history", "table"); page.get_by_role("tablist", name="Attendance layout").get_by_role("tab", name="Everyone").click(); page.wait_for_timeout(300)  # opens per site since round ten
    f = main.get_by_label("Overtime")
    check("History: the overtime box covers each rate and weekend work", f.locator("option").all_inner_texts() == ["All days", "Days with overtime", "Days with time and a half", "Days with double time", "Weekend and bank holiday work"])
    check("History: a Weekend days column beside full and half days", main.locator("thead th").all_inner_texts()[2:5] == ["Full days", "Half days", "Weekend days"])
    month = day[:7]
    want = data(page, f"(() => {{ const r = db.attendance.filter(a => a.date.startsWith('{month}') && a.date <= day && a.status === 'restday'); return [r.length, new Set(r.map(a => a.personId)).size, r.reduce((s, a) => s + a.overtimeHours, 0), r.reduce((s, a) => s + (a.doubleHours ?? 0), 0)] }})()")
    f.select_option("rest"); page.wait_for_timeout(300)
    foot = main.locator("tfoot tr").inner_text().split("\t")
    num = lambda t: 0.0 if t.strip() in ("-", "") else float(t.replace(",", ""))
    check("History: Weekend and bank holiday work shows only the time stamps, with no basic hours", f"{want[0]} attendance entries for {want[1]} people, weekend and bank holiday work only" in main.inner_text() and num(foot[-5]) == want[0] and num(foot[-4]) == 0 and num(foot[-3]) == want[2] and num(foot[-2]) == want[3], (foot, want))
    f.select_option("double"); page.wait_for_timeout(300)
    dd = data(page, f"db.attendance.filter(a => a.date.startsWith('{month}') && a.date <= day && (a.doubleHours ?? 0) > 0).length")
    check("History: Days with double time takes every day that has double time hours", f"{dd} attendance entries" in main.inner_text() and "days with hours at double time only" in main.inner_text(), main.locator("header").inner_text()[:200])
    main.get_by_role("tablist", name="History view").get_by_role("tab", name="Day by day").click(); page.wait_for_timeout(300)
    check("History: day by day shows a day's hours at both rates, and a weekend stamp as its hours", "Full +7.5h x1.5 +1.5h x2" in main.inner_text() and "4h x1.5 + 2h x2" in main.inner_text())
    check("History: fits the page", page.evaluate(SCROLLS) == 0)

    # ── 4. Payroll: Monday to Sunday, the weekend's hours, and the new flag
    go(page, "/people/payroll", "table"); open_last_week(page)
    sun = data(page, plus(-1))
    week_sel = main.get_by_label("Week", exact=True).locator("option").first.inner_text()
    check("Payroll: the week runs Monday to Sunday and ends on the Sunday", f"week ending {int(sun[8:])} " in week_sel and "Monday to Sunday" in main.locator("header").inner_text(), week_sel)
    cols = main.get_by_role("table", name=re.compile("^Hours for the week")).locator("thead th").all_inner_texts()
    check("Payroll: a Sat, Sun column when anyone worked the weekend", "Sat, Sun" in cols and cols.index("Sat, Sun") == 7, cols)
    row = main.get_by_role("table", name=re.compile("^Hours for the week")).locator("tbody tr").filter(has_text="Orla Prunty")
    cells = row.locator("td").all_inner_texts()
    # Her time and a half is the night and the Saturday morning, plus any ordinary late finish the sample data drew for that week.
    o15 = data(page, "(() => { const o = db.people.find(p => p.name==='Orla Prunty').id; const d = new Date(day+'T12:00:00Z'); const back = ((d.getUTCDay() + 6) % 7) + 7; d.setUTCDate(d.getUTCDate() - back); const mon = d.toISOString().slice(0,10); d.setUTCDate(d.getUTCDate() + 6); const sun = d.toISOString().slice(0,10); return db.attendance.filter(a => a.personId===o && a.date>=mon && a.date<=sun).reduce((t, a) => t + (a.overtimeHours||0), 0) })()")
    o15s = f"{o15:g}"
    check("Payroll: the night past midnight and the Saturday are both in Orla Prunty's hours", "Full +7.5h x1.5 +1.5h x2" in cells[4] and cells[7] == "Sat 4h x1.5 + 2h x2" and cells[9] == o15s and o15 >= 11.5 and cells[10] == "3.5", (cells, o15))
    check("Payroll: that much overtime is flagged for a second look", "A lot of overtime" in cells[-1])
    slip = main.get_by_role("table", name=re.compile("^Hours for the week")).locator("tbody tr").filter(has_text="Double time, no time and a half")
    check("Payroll: double time with no time and a half is flagged, with who to ask", slip.count() == 1 and "Full +2h x2" in slip.inner_text() and slip.get_by_role("button", name=re.compile("^Ask ")).count() >= 1, slip.all_inner_texts())
    check("Payroll: the table fits the page", page.evaluate(SCROLLS) == 0)
    page.screenshot(path=f"{OUT}/914-payroll-week.png")
    main.get_by_role("button", name="Mark the week as checked").click(); page.wait_for_timeout(300)
    check("Payroll: checked, the week can go", main.get_by_role("button", name="Export hours to Sage Payroll").is_enabled())
    # A weekend stamp saved after the check means the week is looked at again.
    page.evaluate("(() => { const k = 'cod.data'; const s = JSON.parse(localStorage.getItem(k)); s.state.db.payrollChecks[0].at = s.state.day + 'T00:00:01'; localStorage.setItem(k, JSON.stringify(s)); })()")
    go(page, f"/people/timesheet?site={pid('C719')}", "table")
    main.get_by_role("button", name="Overtime time stamp").click(); page.wait_for_timeout(300)
    d = dlg(); d.get_by_label("Day").select_option(last_sun)
    d.get_by_role("list", name="People to stamp").locator("> li").first.get_by_role("checkbox").check(); d.get_by_label("Hours at double time").fill("3")
    d.get_by_role("button", name="Save time stamp").click(); page.wait_for_timeout(400)
    go(page, "/people/payroll", "table")
    check("Payroll: a time stamp saved after the check means the week is checked again", "Changed since Aidan King checked it" in main.inner_text() and main.get_by_role("button", name="Mark as checked again").count() == 1 and main.get_by_role("button", name="Export hours to Sage Payroll").is_disabled())
    main.get_by_role("button", name="Mark as checked again").click(); page.wait_for_timeout(300)
    with page.expect_download() as dl:
        main.get_by_role("button", name="Export hours to Sage Payroll").click()
    page.wait_for_timeout(300)
    text = open(dl.value.path(), encoding="utf-8").read()
    line = [l for l in text.splitlines() if ",Prunty,Orla," in l][0]
    check("Payroll: the file ends the week on the Sunday and carries the weekend's hours", dl.value.suggested_filename == f"sage-payroll-hours-week-ending-{sun}.csv" and re.search(rf"{sun[8:]}/{sun[5:7]}/{sun[:4]},\d+\.\d\d,{o15:.2f},3\.50$", line) is not None, (dl.value.suggested_filename, line))

    # ── 5. Bank holidays in Admin
    reset(page)
    go(page, "/admin/bank-holidays", "table")
    side = page.get_by_role("navigation", name="Admin screens")
    check("Admin: Company holidays in the sidebar (Bank holidays until 19 Nov)", side.get_by_role("link", name="Company holidays").count() == 1)
    t = main.get_by_role("table", name=f"Company holidays in {day[:4]}").locator("tbody tr")
    check("Admin: the public holidays are built in for the year", t.count() == 10 and "St Brigid's Day" in t.nth(1).inner_text() and "October bank holiday" in main.inner_text() and main.get_by_role("tablist", name="Year").get_by_role("tab").count() == 2, t.all_inner_texts()[:3])
    check("Admin: a bank holiday that was worked says so", "2 time stamps at double time" in t.filter(has_text="October bank holiday").inner_text())
    main.get_by_role("button", name="Add day").click(); page.wait_for_timeout(150)
    check("Admin: a date is needed", "Pick the date" in main.get_by_role("alert").inner_text())
    main.get_by_label("Date", exact=True).fill(bh["date"]); main.get_by_label("Name", exact=True).last.fill("Again"); main.get_by_role("button", name="Add day").click(); page.wait_for_timeout(150)
    check("Admin: a day already on the list is refused", f"{bh['name']} is already on that date" in main.get_by_role("alert").inner_text())
    fri = data(page, plus(-3))
